<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Image Preview</title>
  <script src="https://unpkg.com/react@18/umd/react.development.js" crossorigin></script>
  <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js" crossorigin></script>
  <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
  <style>
    :root {
      --bg-color: #121212;
      --text-color: #e0e0e0;
      --accent-color: #bb86fc;
      --error-color: #cf6679;
      --dialog-bg: #1e1e1e;
      --border-color: #333;
    }

    body {
      font-family: system-ui, -apple-system, sans-serif;
      background-color: var(--bg-color);
      color: var(--text-color);
      margin: 0;
      padding: 2rem;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 1rem;
    }

    .image-preview {
      max-width: 100%;
      border: 1px solid var(--border-color);
      border-radius: 8px;
      padding: 1rem;
      background-color: var(--dialog-bg);
      text-align: center;
    }

    .image-preview img {
      max-width: 100%;
      height: auto;
      border-radius: 4px;
      margin-bottom: 1rem;
    }

    button {
      background-color: transparent;
      color: var(--text-color);
      border: 1px solid var(--border-color);
      padding: 0.5rem 1rem;
      border-radius: 4px;
      cursor: pointer;
      font-size: 1rem;
      transition: background-color 0.2s, border-color 0.2s;
    }

    button:hover, button:focus-visible {
      background-color: rgba(255, 255, 255, 0.1);
      outline: 2px solid var(--accent-color);
      outline-offset: 2px;
    }

    button.trigger {
      color: var(--error-color);
      border-color: var(--error-color);
    }

    button.trigger:hover, button.trigger:focus-visible {
      background-color: rgba(207, 102, 121, 0.1);
      outline-color: var(--error-color);
    }

    dialog {
      background-color: var(--dialog-bg);
      color: var(--text-color);
      border: 1px solid var(--border-color);
      border-radius: 8px;
      padding: 1.5rem;
      max-width: 400px;
      box-shadow: 0 4px 6px rgba(0, 0, 0, 0.5);
    }

    dialog::backdrop {
      background-color: rgba(0, 0, 0, 0.7);
      backdrop-filter: blur(2px);
    }

    dialog h2 {
      margin-top: 0;
      font-size: 1.25rem;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.5rem;
      margin-top: 1.5rem;
    }

    .delete-confirm {
      background-color: var(--error-color);
      color: #000;
      border-color: var(--error-color);
    }

    .delete-confirm:hover, .delete-confirm:focus-visible {
      background-color: #e57373;
      outline-color: #e57373;
    }
  </style>
</head>
<body>
  <div id="root"></div>
  <script type="text/babel">
    const { useState, useRef, useEffect } = React;

    function ImagePreviewApp() {
      const [isDeleted, setIsDeleted] = useState(false);
      const [isDialogOpen, setIsDialogOpen] = useState(false);
      const dialogRef = useRef(null);
      const triggerRef = useRef(null);

      useEffect(() => {
        const dialogNode = dialogRef.current;
        if (isDialogOpen) {
          if (dialogNode && !dialogNode.open) {
            dialogNode.showModal();
          }
        } else {
          if (dialogNode && dialogNode.open) {
            dialogNode.close();
          }
        }
      }, [isDialogOpen]);

      const openDialog = () => {
        setIsDialogOpen(true);
      };

      const closeDialog = () => {
        setIsDialogOpen(false);
      };

      const handleDelete = () => {
        setIsDialogOpen(false);
        setIsDeleted(true);
      };

      // Handle the case where dialog is closed by Escape key
      const handleDialogClose = () => {
        setIsDialogOpen(false);
      };

      return (
        <main>
          <h1 className="visually-hidden">Image Details</h1>
          {!isDeleted ? (
            <div className="image-preview">
              <img src="https://placehold.co/600x400/333/eee?text=Image+Preview" alt="Placeholder image for preview" />
              <div>
                <button
                  type="button"
                  className="trigger"
                  onClick={openDialog}
                  ref={triggerRef}
                >
                  Delete Image
                </button>
              </div>
            </div>
          ) : (
            <div
              className="image-preview"
              aria-live="polite"
              tabIndex="-1"
              ref={(node) => {
                if (node) node.focus();
              }}
            >
              <p>Image deleted successfully.</p>
            </div>
          )}

          <dialog
            ref={dialogRef}
            onClose={handleDialogClose}
            aria-labelledby="dialog-title"
          >
            <h2 id="dialog-title">Delete Image</h2>
            <p>Are you sure you want to delete this image from your library? This action cannot be undone.</p>
            <div className="dialog-actions">
              <button type="button" onClick={closeDialog}>Cancel</button>
              <button type="button" className="delete-confirm" onClick={handleDelete}>Delete</button>
            </div>
          </dialog>
        </main>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<ImagePreviewApp />);
  </script>
</body>
</html>
